    });
  }

  if (!rconSuccess) {
    await interaction.editReply({ content: 'Could not send in-game warning (RCON failed). Restarting anyway in 30 seconds.' });
  }

  // Wait 30 seconds before restarting
  await new Promise(res => setTimeout(res, 30000));

  await interaction.editReply({ content: `Restarting server \n\`\`\`${containerName}\`\`\`...` });
  exec(`docker restart ${containerName}`, (error, stdout, stderr) => {
