import { Rcon } from 'rcon-client';

export async function sendRconMessage({ host, port, password, message }: { host: string, port: number, password: string, message: string }) {
  const rcon = new Rcon({ host, port, password });
  try {
    await rcon.connect();
    // Use 'say' instead of '/say' for Minecraft RCON
    const result = await rcon.send(`say ${message}`);
    await rcon.end();
    return { success: true, result };
  } catch (err) {
    await rcon.end().catch(() => {});
    return { success: false, error: err instanceof Error ? err.message : String(err) };
  }
}

